-- IDs and kinds only: deleted private content is never copied into this log.
CREATE TABLE library_sync_state(id INTEGER PRIMARY KEY CHECK(id=1),epoch TEXT NOT NULL,floor INTEGER NOT NULL DEFAULT 0);
INSERT INTO library_sync_state(id,epoch) VALUES(1,lower(hex(randomblob(16))));
CREATE TABLE library_sync_changes(seq INTEGER PRIMARY KEY AUTOINCREMENT,link_id INTEGER,kind TEXT NOT NULL CHECK(kind IN ('upsert','delete','taxonomy')),created_at INTEGER NOT NULL DEFAULT(unixepoch()));
CREATE INDEX library_sync_retention ON library_sync_changes(created_at,seq);
INSERT INTO library_sync_changes(link_id,kind) SELECT id,'upsert' FROM links;
CREATE TRIGGER library_sync_links_insert AFTER INSERT ON links BEGIN INSERT INTO library_sync_changes(link_id,kind) VALUES(NEW.id,'upsert'); END;
CREATE TRIGGER library_sync_links_update AFTER UPDATE ON links BEGIN INSERT INTO library_sync_changes(link_id,kind) VALUES(NEW.id,'upsert'); END;
CREATE TRIGGER library_sync_links_delete AFTER DELETE ON links BEGIN INSERT INTO library_sync_changes(link_id,kind) VALUES(OLD.id,'delete'); END;
