CREATE TRIGGER library_sync_curation_overrides_update AFTER UPDATE ON curation_overrides BEGIN INSERT INTO library_sync_changes(link_id,kind) VALUES(NEW.link_id,'upsert'); END;
CREATE TRIGGER library_sync_curation_overrides_delete AFTER DELETE ON curation_overrides BEGIN INSERT INTO library_sync_changes(link_id,kind) VALUES(OLD.link_id,'upsert'); END;
