CREATE TRIGGER library_sync_custom_tags_insert AFTER INSERT ON custom_tags BEGIN INSERT INTO library_sync_changes(kind) VALUES('taxonomy'); INSERT INTO library_sync_changes(link_id,kind) SELECT link_id,'upsert' FROM custom_tag_links WHERE tag_id=NEW.id; END;
CREATE TRIGGER library_sync_custom_tags_update AFTER UPDATE ON custom_tags BEGIN INSERT INTO library_sync_changes(kind) VALUES('taxonomy'); INSERT INTO library_sync_changes(link_id,kind) SELECT link_id,'upsert' FROM custom_tag_links WHERE tag_id=NEW.id; END;
CREATE TRIGGER library_sync_custom_tags_delete AFTER DELETE ON custom_tags BEGIN INSERT INTO library_sync_changes(kind) VALUES('taxonomy'); INSERT INTO library_sync_changes(link_id,kind) SELECT link_id,'upsert' FROM custom_tag_links WHERE tag_id=OLD.id; END;
